window.products.push({"id":491335,"name":"SignJoker] Gymnastics Street Sign New Gymnast Leotards Gift Novelty Street Sign Wall Plaque Decoration","category":"homeandappliances","retail price":14.95,"sale price":null,"image":"https://m.media-amazon.com/images/I/31-Ot6n0XmL._AC_.jpg","description":"Our novelty signs are made from outdoor durable plastic. These signs will never rust or fade, perfect inside or out (4-5 years outdoors)! The sign has round corners and a hole pre-drilled for easy mounting. Please check out all our other signs, they make the perfect gift for any occasion.","images":["https://m.media-amazon.com/images/I/31-Ot6n0XmL._AC_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"SignJoker","source_asin":"B06XZQQ27D","category_path":"Home & Kitchen"},"sku":"BM-491335","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B06XZQQ27D","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B06XZQQ27D","price_pending":true,"merchant_ready":false});
